void DopplerMeasurementXmlDeserializer::deserialize(
   mxml_node_t* const dmNode,
   DopplerMeasurement& dplMeasurement)
{
   if (getAttributeValue(dmNode, AT_NAM_WAVELENGTH, dplMeasurement.wavelength))
   {
      mxml_node_t* const childNode = getElementNodeFromPath(dmNode, EL_DOPPLER);

      if (childNode != nullptr)
      {
         StochasticVariableXmlDeserializer::deserialize(childNode, dplMeasurement.doppler);
      }
      else
      {
         throw XmlSerializationException(
            "DopplerMeasurementXmlDeserializer: Child element missing: " + std::string(EL_DOPPLER));
      }
   }
   else
   {
      throw XmlSerializationException(
         "DopplerMeasurementXmlDeserializer: Attribute missing or wrong type: "
         + std::string(AT_NAM_WAVELENGTH));
   }
}

