/// @brief Find a package with an epoch time that matches exactly with the one attached to a
   ///        data-point.
   ///
   /// @param iterator The iterator pointing to the first package that corresponds to a time-stamp
   ///                 that is not less than the data time-stamp.
   /// @param time     The time-stamp of the data to be inserted.
   ///
   /// @return An iterator pointing to the package in which the data can be inserted, or end() if we
   ///         cannot match based on this time requirement.
   ///
   Iterator handleAsOnTime(const Iterator& iterator, const Time& time)
   {
      // If the iterator points to a package with the same time, we can insert data into it.
      return (iterator != m_packages.end() && compareEqual(iterator->getTime(), time))
              ? iterator
              : m_packages.end();
   }

