void HlfStartTimeHeaderRecord::encodePayload(BufferWriter& writer) const
{
   // HLF Start Time Header payload consists of:
   // - Sub Type:              1 byte
   // - Recording Start Time:  20 bytes
   // - Start Uptime:          8 bytes

   uint8_t const subType{static_cast<uint8_t>(getSubType())};

   // Encode payload fields
   writer.write(&subType, sizeof(uint8_t));
   encodeIso8601(writer, m_recordingStartTime);
   writer.write(&m_startUptime, sizeof(uint64_t));
}

void consumer(ThreadSafeQueue<std::shared_ptr<int>>* queue, std::atomic<int>* itemsPopped)
{
   std::cout << "Consumer started" << '\n';
   while (*itemsPopped < TOTAL_ITEMS)
   {
      std::shared_ptr<int> popped;
      if (queue->tryPop(popped))
      {
         // Validate the pointer is not null
         REQUIRE(popped != nullptr);
         (*itemsPopped)++;
      }
      else
      {
         // Nothing to pop yet, yield so producers can enqueue
         std::this_thread::yield();
      }
   }
}

