std::optional<SatelliteCorrections> getSatelliteCorrections(
   const GnssKey& sanitizedKey,
   const Corrections& corrections,
   const Time& measurementTime,
   const PseudorangeMeasurement& pseudorange,
   const GnssKeyMap<ClockAndCounter>& cachedClocks)
{
   // First check if all mandatory satellite-level corrections are available and valid.

   // Satellite clock correction is mandatory and must be time-valid for the measurement.
   auto clock = getClock(sanitizedKey, cachedClocks, corrections, measurementTime, pseudorange);
   if (!clock)
   {
      return std::nullopt;
   }

   // Satellite position correction is mandatory
   const auto satPosIter = corrections.data.satellitePosition.find(sanitizedKey);
   if (satPosIter == corrections.data.satellitePosition.end())
   {
      return std::nullopt;
   }

   // Slant troposphere correction is mandatory
   const auto tropoIter = corrections.data.slantTroposphere.find(sanitizedKey);
   if (tropoIter == corrections.data.slantTroposphere.end())
   {
      return std::nullopt;
   }

   // Slant ionosphere correction is mandatory
   const auto ionoIter = corrections.data.slantIonosphere.find(sanitizedKey);
   if (ionoIter == corrections.data.slantIonosphere.end())
   {
      return std::nullopt;
   }

   // Having checked that all mandatory corrections are available, populate the output structure.

   SatelliteCorrections result;
   result.clockDiscontinuityCounter = clock->discontinuityCounter;
   result.satellitePosition = satPosIter->second;
   result.satelliteLineOfSightCorrections = std::make_tuple(
      clock->clock,
      TroposphereCorrection{tropoIter->second.data.bias, tropoIter->second.time});
   result.iono = IonosphereCorrection{ionoIter->second.data.bias, ionoIter->second.time};
   return result;
}

std::shared_ptr<ProvideCorrectionsInvocation>
ApiInvocationXmlDeserializer::createProvideCorrectionsInvocation(
   mxml_node_t* const apiInvocationNode,
   uint16_t streamId,
   ErrorCode errorCode)
{
   std::shared_ptr<ProvideCorrectionsInvocation> provideCorrectionsInvocation = nullptr;


   if (
      mxml_node_t* const correctionsNode
      = getElementNodeFromPath(apiInvocationNode, PATH_CORRECTIONS))
   {
      auto correctionsPtr = std::make_shared<Corrections>();

      // The deserialize takes a reference, so need to convert
      Corrections& corrections = *correctionsPtr;

      CorrectionsCollectionXmlDeserializer::deserialize(correctionsNode, corrections);

      provideCorrectionsInvocation
         = std::make_shared<ProvideCorrectionsInvocation>(streamId, errorCode, correctionsPtr);
   }
   else
   {
      throw XmlSerializationException(
         "ApiInvocationXmlDeserializer: Could not find Element: " + std::string(PATH_CORRECTIONS));
   }

   return provideCorrectionsInvocation;
}

void HlfEndTimeHeaderRecord::decodePayload(BufferReader& reader)
{
   // HLF End Time Header payload consists of:
   // - Sub Type:   1 byte
   // - End Uptime: 8 bytes

   // Read and verify sub-type is correct for this record type
   uint8_t subType{0U};
   reader.read(&subType, sizeof(uint8_t));

   if (subType == static_cast<uint8_t>(getSubType()))
   {
      // Decode header-specific fields
      reader.read(&m_endUptime, sizeof(uint64_t));
   }
}

