void ConversionManager::convertToHlf()
{
   const auto converterConfig = RuntimeConfig::getConverterConfig();
   const std::filesystem::path& inputFilePath = converterConfig.inputFilePath;

   // Ensure the input file exists and is not empty before starting.
   if (!std::filesystem::exists(inputFilePath))
   {
      throw FileException("Input file does not exist: " + inputFilePath.string());
   }

   if (std::filesystem::file_size(inputFilePath) == 0)
   {
      throw FileException("Input file is empty: " + inputFilePath.string());
   }

   m_fileManager.safeClose();
   m_fileManager.openOutput(converterConfig.outputFilePath, true);

   m_validBytes = ZERO_SIZE; // Reset the scratch buffer state.

   // Initialize deserialization status to a known state before starting
   m_deserializeStatus = IHlfRecordDeserializable::HlfDeserializeStatus::Success;

   m_textToHlfDeserializer->setFileToDecode(inputFilePath.string());

   m_writerRunning.store(true);
   std::thread writerThread(&ConversionManager::writeHlfToFile, this);

   m_textToHlfDeserializer->parseTextFile();

   bool waitingForWriter = true;

   // Wait for the writer thread to finish
   while (waitingForWriter)
   {
      {
         std::scoped_lock<std::mutex> lock(m_hlfRecordsMutex);
         waitingForWriter = !m_hlfRecords.empty();
      }

      std::this_thread::sleep_for(std::chrono::milliseconds(WRITER_POLL_INTERVAL_MS));
   }

   m_writerRunning.store(false);
   writerThread.join();

   m_fileManager.safeClose();

   // Check if the deserialization process has completed with an error.
   if (m_deserializeStatus == IHlfRecordDeserializable::HlfDeserializeStatus::Error)
   {
      throw GeneralException(m_deserializeError);
   }
}

constexpr std::uint32_t Crc32::reflect(std::uint32_t data, const std::uint8_t nBits) noexcept
{
   std::uint32_t reflection = 0U;

   for (std::uint8_t bit = 0U; bit < nBits; ++bit)
   {
      if ((data & ONE) != ZERO)
      {
         reflection |= (ONE << (nBits - ONE - bit));
      }
      data >>= ONE;
   }

   return reflection;
}

